#include <Arduino.h>

#define LED_PIN 2

void setup() {
  Serial.begin(115200);
  delay(1500);

  pinMode(LED_PIN, OUTPUT);

  Serial.println();
  Serial.println("RAVA ESP32-S3 TEST");
  Serial.println("Board started successfully!");
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  Serial.println("RAVA: ON");
  delay(1000);

  digitalWrite(LED_PIN, LOW);
  Serial.println("RAVA: OFF");
  delay(1000);
}
